const sender = ''; // Inserisci l'indirizzo e-mail esatto del mittente autorizzato.
const publish = false; // Passa a true solo dopo la prova con Gmail e GitHub.
const subject = ''; // Inserisci qui l’oggetto esatto in minuscolo.
if (!subject || !/^[\w.+-]+@[\w.-]+\.[a-z]{2,}$/i.test(sender)) {
  throw new Error('Impostare l’indirizzo del mittente autorizzato nel nodo Configura mittente.');
}
return [{json:{sender:sender.toLowerCase(),subject,publish,query:'to:n.valigi@gmail.com from:'+sender+' subject:"'+subject+'" newer_than:2d -in:spam -in:trash'}}];

const config = $('Configura mittente').first().json;
const mail = $input.all().map(item => item.json)
  .filter(item => item.subject?.trim().toLowerCase() === config.subject
    && item.from?.value?.length === 1
    && item.from.value[0].address?.toLowerCase() === config.sender)
  .sort((a,b) => Date.parse(b.date) - Date.parse(a.date))[0];
if (!mail) return [];
const text = mail.text || '';
if (!text || text.length > 14000) throw new Error('L’aggiornamento non contiene un testo semplice utilizzabile.');
const headings = [
  { id:'ai', it:['agenti ai','ai agents','agenti ai, integrazione di sistemi e gestione del prodotto'], en:['ai agents','ai agents, system integration and product management'] },
  { id:'web', it:['sviluppo web','sviluppo web, e-commerce e ricerca di mercato'], en:['web development','web development, e-commerce and market research'] },
  { id:'data', it:['dati e gis','dati e geo-intelligence: gis 3d e catasto'], en:['data and gis','geo-intelligence: 3d gis and cadastral data'] },
  { id:'infra', it:['infrastruttura e stack','infrastruttura e tecnologie'], en:['infrastructure and stack','infrastructure and technologies'] },
];
const updates = { it: [], en: [] };
const aliases = { italiano:'it', italian:'it', english:'en', inglese:'en' };
let lang, section, entry;
for (const raw of text.split(/\r?\n/)) {
  const line = raw.trim();
  if (!line) continue;
  if (/^(?:--$|>)/.test(line)) throw new Error('Rimuovere firme e citazioni dal testo da pubblicare.');
  const clean = line.replace(/^#{1,6}\s+/, '').replace(/^[-*•]\s+/, '').replace(/\*\*/g, '');
  const key = clean.toLowerCase().replace(/:$/, '');
  if (aliases[key]) { lang = aliases[key]; section = undefined; entry = undefined; continue; }
  if (!lang) continue;
  const heading = headings.find(h => h[lang].includes(key));
  if (heading) { section = heading.id; entry = undefined; continue; }
  const pair = clean.match(/^([^:]{4,100}):\s+(.{15,})$/);
  if (section && pair) {
    entry = {section, title:pair[1].trim(), body:pair[2].trim()};
    updates[lang].push(entry);
  } else if (entry && !clean.includes(':')) {
    entry.body += ' ' + clean;
  } else {
    throw new Error('Formato non riconosciuto. Usare sezioni per lingua e voci Titolo: descrizione.');
  }
}
for (const langKey of ['it','en']) {
  const list = updates[langKey];
  if (!list.length || list.length > 12) throw new Error('Sono necessarie da una a dodici voci per lingua.');
  for (const item of list) {
    if (item.body.length > 900 || /[<>@]|https?:|www\.|\b(?:password|token|api[ _-]?key)\s*[:=]/i.test(item.title + ' ' + item.body)) {
      throw new Error('Una voce supera i limiti o contiene dati da verificare prima della pubblicazione.');
    }
  }
}
const order = list => list.map(item => item.section).sort().join(',');
if (order(updates.it) !== order(updates.en)) throw new Error('Le due lingue devono coprire le stesse sezioni e lo stesso numero di voci.');
return [{json:{updates}}];

const response = $input.first().json;
const repo = response.data?.repository;
const head = repo?.ref?.target?.oid;
if (response.errors?.length || !/^[a-f0-9]{40}$/.test(head || '')) throw new Error('Lettura del repository non riuscita.');
const updates = $('Interpreta aggiornamento').first().json.updates;
const headings = {
  it:{ai:'Agenti AI, integrazione di sistemi e gestione del prodotto',web:'Sviluppo web, e-commerce e ricerca di mercato',data:'Dati e geo-intelligence: GIS 3D e catasto',infra:'Infrastruttura e tecnologie'},
  en:{ai:'AI agents, system integration and product management',web:'Web development, e-commerce and market research',data:'Geo-intelligence: 3D GIS and cadastral data',infra:'Infrastructure and technologies'}
};
const escape = value => value.replace(/[&"'<>]/g, ch => ({'&':'&amp;','"':'&quot;',"'":'&#39;','<':'&lt;','>':'&gt;'}[ch]));
const norm = value => value.normalize('NFKC').toLowerCase().replace(/&amp;/g,'&').replace(/&#39;|&rsquo;|’/g,"'").trim();
const additions = [], checks = {};
for (const lang of ['it','en']) {
  const original = repo[lang]?.text;
  if (!original || !original.includes('</html>')) throw new Error('Pagina delle competenze mancante o incompleta.');
  let html = original;
  checks[lang] = [];
  for (const item of updates[lang]) {
    const heading = '<h2>'+headings[lang][item.section]+'</h2>';
    const start = html.indexOf(heading);
    const end = html.indexOf('</article>',start);
    if (start < 0 || end < 0 || html.indexOf(heading,start+1) >= 0) throw new Error('Sezione ambigua nella pagina.');
    let block = html.slice(start,end);
    const generated = '<li><strong>'+escape(item.title)+'</strong>. '+escape(item.body)+'</li>';
    const matches = [...block.matchAll(/<li><strong>([^<]+)<\/strong>[^\n]*?<\/li>/g)]
      .filter(match => norm(match[1]) === norm(item.title));
    if (matches.length > 1) throw new Error('Titolo duplicato nella sezione.');
    if (matches.length === 1) {
      const match = matches[0];
      block = block.slice(0,match.index) + generated + block.slice(match.index+match[0].length);
    } else {
      const open = block.lastIndexOf('<ul class="numeri">');
      const close = block.indexOf('    </ul>',open);
      if (open < 0 || close < 0) throw new Error('Elenco delle competenze non trovato.');
      block = block.slice(0,close) + '      ' + generated + '\n' + block.slice(close);
    }
    html = html.slice(0,start)+block+html.slice(end);
    checks[lang].push(generated);
  }
  if (html !== original) {
    additions.push({path:lang === 'it' ? 'competenze.html' : 'en/skills.html', contents:Buffer.from(html,'utf8').toString('base64')});
  }
}
const publish = $('Configura mittente').first().json.publish;
return [{json:{head,additions,checks,changed:additions.length>0,publish}}];

const result = $input.first().json;
if (result.changed && !result.publish) return [{json:{status:'Simulazione: nessun commit',files:result.additions.map(item=>item.path)}}];
return [{json:{status:'Nessuna modifica da pubblicare'}}];

const checks = $('Aggiorna solo le competenze').first().json.checks;
for (const [lang, node] of [['it','Leggi pagina italiana'],['en','Leggi pagina inglese']]) {
  const html = $(node).first().json.body;
  if (typeof html !== 'string' || !checks[lang].every(item => html.includes(item))) {
    throw new Error('Vercel non mostra ancora tutte le competenze nella pagina '+lang+'. Controllare lo stato del deploy.');
  }
}
return [{json:{status:'Pubblicazione verificata',pages:['https://www.nicvaligi.com/competenze.html','https://www.nicvaligi.com/en/skills.html']}}];
